insert into sector_profiles (settore, version, status, pack, changelog)
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('veterinario', 1, 'production', 'info_trattamenti', 'Ogni quanto si fa il richiamo del vaccino?', $q08swy4$["ogni quanto va fatto il richiamo","ogni quanto si fa il vaccino","ogni quanto va fatto il vaccino","ogni quanto si vaccina il cane","ogni quanto si vaccina il gatto","ogni quanto va rifatto il vaccino","quando si fa il richiamo"]$q08swy4$::jsonb, 'Dopo il ciclo iniziale da cucciolo si fa in genere un richiamo periodico, spesso annuale. Frequenza e tipo di vaccino però dipendono da specie, età, stile di vita e dal protocollo che indica il veterinario.', $q2dam2l${}$q2dam2l$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('veterinario', 1, 'production', 'info_trattamenti', 'A che età si vaccina un cucciolo?', $quvsnwh$["quando si vaccina un cucciolo","a che eta si fa il primo vaccino","quando fare il primo vaccino al cucciolo","a che eta si vaccina un gattino","primo vaccino del cucciolo"]$quvsnwh$::jsonb, 'I cuccioli iniziano in genere un ciclo di vaccinazioni nelle prime settimane di vita, con più dosi a distanza di alcune settimane. Il calendario preciso lo stabilisce il veterinario in visita.', $q2y1osb${}$q2y1osb$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('veterinario', 1, 'production', 'info_trattamenti', 'Cosa serve per il passaporto europeo dell''animale?', $q7vjcnc$["cosa serve per il passaporto","come si fa il passaporto per il cane","come si fa il passaporto per il gatto","cosa serve per fare il passaporto","documenti per il passaporto del cane"]$q7vjcnc$::jsonb, 'In genere servono il microchip e la vaccinazione antirabbica in regola, e il passaporto viene rilasciato da un veterinario abilitato. I requisiti cambiano in base al Paese di destinazione: conviene informarsi con la clinica con un certo anticipo.', $qqocrho${}$qqocrho$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('veterinario', 1, 'production', 'info_trattamenti', 'Cosa serve per viaggiare con il cane o il gatto?', $qqq5o25$["cosa serve per viaggiare con il cane","cosa serve per viaggiare con il gatto","come faccio a viaggiare con il cane","come viaggiare con il mio animale","documenti per viaggiare con il cane","certificato per viaggiare"]$qqq5o25$::jsonb, 'Dipende da destinazione e mezzo di trasporto: di solito servono identificazione con microchip, vaccinazioni in regola e documenti sanitari. Le regole cambiano, quindi è bene chiedere alla clinica e verificare i requisiti del Paese di arrivo e del vettore.', $qwosdxg${}$qwosdxg$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('veterinario', 1, 'production', 'info_trattamenti', 'Il microchip è obbligatorio?', $qin56zu$["il microchip e obbligatorio","serve il microchip","e obbligatorio il microchip per il cane","e obbligatorio il microchip per il gatto","devo mettere il microchip"]$qin56zu$::jsonb, 'Per i cani il microchip e l''iscrizione all''anagrafe sono previsti dalla normativa italiana. Per gatti e altri animali conviene chiedere alla clinica, anche in base ad esempio ai viaggi.', $qk7gmxg${}$qk7gmxg$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('veterinario', 1, 'production', 'info_trattamenti', 'Il microchip fa male?', $q84c0ya$["fa male il microchip","come si mette il microchip","come funziona il microchip","come si inserisce il microchip","cos e il microchip"]$q84c0ya$::jsonb, 'Il microchip è molto piccolo e viene inserito sotto la pelle con una breve iniezione. Il veterinario spiega come procede e registra i dati.', $q8usaoo${}$q8usaoo$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('veterinario', 1, 'production', 'info_trattamenti', 'Quando si sterilizza o castra un animale?', $q48zjug$["a che eta si sterilizza","a che eta si castra","quando si sterilizza una gatta","quando si sterilizza una cagna","quando si castra un cane","quando si castra un gatto","a che eta si fa la sterilizzazione"]$q48zjug$::jsonb, 'Il momento più adatto dipende da specie, razza, taglia, sesso e condizioni dell''animale: lo stabilisce il veterinario durante la visita.', $qlsh38f${}$qlsh38f$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('veterinario', 1, 'production', 'info_trattamenti', 'Come funziona la sterilizzazione?', $qf31dk7$["cos e la sterilizzazione","come funziona la castrazione","in cosa consiste la sterilizzazione","in cosa consiste la castrazione","differenza tra sterilizzazione e castrazione","come si fa la sterilizzazione"]$qf31dk7$::jsonb, 'Sterilizzazione e castrazione sono interventi chirurgici eseguiti in anestesia generale, con tecniche diverse per femmine e maschi. Il veterinario spiega modalità, preparazione e decorso dopo la visita.', $qadkae4${}$qadkae4$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('veterinario', 1, 'production', 'info_trattamenti', 'Serve il digiuno prima di un intervento?', $qcrqzbm$["serve il digiuno","devo far digiunare l animale","digiuno prima dell intervento","cosa devo fare prima dell intervento","preparazione all intervento","preparazione alla sterilizzazione"]$qcrqzbm$::jsonb, 'Prima di un intervento o di una sedazione la clinica dà indicazioni precise su digiuno e preparazione: vanno seguite quelle fornite dalla propria clinica.', $qf3z88q${}$qf3z88q$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('veterinario', 1, 'production', 'info_trattamenti', 'Ogni quanto si fa l''antiparassitario?', $qeqba1k$["ogni quanto va fatto l antiparassitario","ogni quanto si da l antipulci","ogni quanto si mette l antipulci","ogni quanto si fa l antizecche","ogni quanto si da il vermifugo","ogni quanto va fatto il vermifugo","ogni quanto si vermifuga","ogni quanto si sverma"]$qeqba1k$::jsonb, 'La frequenza dipende dal prodotto, dall''età, dallo stile di vita e dal periodo dell''anno: il veterinario indica prodotto e cadenza adatti. I prodotti sono specifici per specie e peso, per questo non vanno scambiati tra animali diversi.', $qyi7c5o${}$qyi7c5o$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('veterinario', 1, 'production', 'info_trattamenti', 'Cosa si fa nella prima visita?', $qrtjt9h$["cosa succede alla prima visita","come funziona la prima visita","in cosa consiste la prima visita","cosa comprende la prima visita","come si svolge la prima visita"]$qrtjt9h$::jsonb, 'In genere il veterinario raccoglie alcune informazioni sull''animale (età, alimentazione, abitudini, eventuali problemi), fa un controllo generale e imposta con il proprietario vaccini, prevenzione e un piano di controlli.', $qt7y1gh${}$qt7y1gh$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('veterinario', 1, 'production', 'info_documenti', 'Cosa devo portare alla visita?', $qhbf3k3$["cosa devo portare alla prima visita","cosa serve portare dal veterinario","cosa devo portare dal veterinario","che documenti servono per la visita","cosa porto alla visita"]$qhbf3k3$::jsonb, 'È utile portare il libretto sanitario o il passaporto, il documento del proprietario, eventuali esami o referti precedenti e l''elenco di farmaci o integratori che l''animale assume. Per gatti e animali piccoli serve un trasportino, per i cani il guinzaglio. Per indicazioni specifiche verifichi con la clinica.', $qqbim83${}$qqbim83$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('veterinario', 1, 'production', 'info_trattamenti', 'Ogni quanto è bene fare un controllo?', $qq1ys59$["ogni quanto va fatto il controllo","ogni quanto si porta il cane dal veterinario","ogni quanto si porta il gatto dal veterinario","ogni quanto va fatta la visita di controllo","quante volte l anno si porta dal veterinario"]$qq1ys59$::jsonb, 'Per un animale adulto e in salute si consiglia in genere un controllo periodico, spesso annuale; cuccioli e animali anziani hanno bisogno di controlli più ravvicinati. Il veterinario indica la frequenza giusta per ciascun animale.', $qen6ka3${}$qen6ka3$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('veterinario', 1, 'production', 'info_trattamenti', 'A cosa servono le analisi del sangue?', $qujjbfh$["a cosa servono le analisi","perche si fanno le analisi del sangue","cosa controllano le analisi del sangue","servono le analisi del sangue","come funzionano le analisi del sangue"]$qujjbfh$::jsonb, 'Le analisi del sangue aiutano il veterinario a valutare lo stato di salute generale e il funzionamento degli organi. Quali esami fare lo decide il veterinario in base all''animale.', $q0nhjh2${}$q0nhjh2$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('veterinario', 1, 'production', 'info_trattamenti', 'Come funziona l''ecografia?', $qi289by$["cos e l ecografia","a cosa serve l ecografia","in cosa consiste l ecografia","l ecografia fa male","come si fa l ecografia"]$qi289by$::jsonb, 'L''ecografia è un esame non invasivo che permette di osservare gli organi interni. In alcuni casi serve rasare una piccola zona di pelo; il veterinario indica quando è utile.', $qo8ox2j${}$qo8ox2j$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('veterinario', 1, 'production', 'info_trattamenti', 'Come funziona la pulizia dei denti negli animali?', $qbqo1xb$["come si fa la pulizia dei denti al cane","come si fa la pulizia dei denti al gatto","cosa comporta la pulizia dei denti","la pulizia dei denti si fa con l anestesia","cos e la detartrasi","cosa si fa nella pulizia dei denti"]$qbqo1xb$::jsonb, 'La pulizia dei denti professionale rimuove placca e tartaro e in genere richiede una sedazione o un''anestesia, per poter lavorare in sicurezza. Il veterinario valuta in visita se è indicata.', $q1h0uwc${}$q1h0uwc$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('veterinario', 1, 'production', 'info_trattamenti', 'Posso portare un animale in gravidanza dal veterinario?', $qnt6gr1$["la mia cagna e incinta","la mia gatta e incinta","visita in gravidanza","gravidanza del cane","gravidanza della gatta","cosa fare in gravidanza"]$qnt6gr1$::jsonb, 'Durante la gravidanza è importante una visita veterinaria per seguirne l''andamento e organizzarsi per il parto. Per i dettagli conviene prenotare una visita con la clinica.', $qz5lqfu${}$qz5lqfu$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('veterinario', 1, 'production', 'info_trattamenti', 'Il vaccino è necessario per un gatto che vive in casa?', $q4kg29h$["serve il vaccino al gatto di casa","il gatto che non esce deve vaccinarsi","vaccino gatto da appartamento","il cane che non esce deve vaccinarsi"]$q4kg29h$::jsonb, 'La scelta dei vaccini dipende da specie, età, stile di vita e rischi per quell''animale, anche se vive in casa. Il veterinario valuta caso per caso.', $q0yosvo${}$q0yosvo$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('veterinario', 1, 'production', 'info_trattamenti', 'Quanto dura una visita veterinaria?', $qs83i1l$["quanto dura la visita","quanto tempo ci vuole per la visita","quanto dura la visita dal veterinario","quanto dura un controllo"]$qs83i1l$::jsonb, 'La durata varia in base al motivo della visita e alle esigenze dell''animale: per un''indicazione precisa conviene chiedere alla clinica al momento della prenotazione.', $qktdf1s${}$qktdf1s$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('veterinario', 1, 'production', 'info_trattamenti', 'Come porto il gatto dal veterinario?', $q45to94$["come porto il gatto in clinica","come trasportare il gatto","trasportino per il gatto","come porto il coniglio dal veterinario","come trasportare un animale piccolo"]$q45to94$::jsonb, 'Gatti e animali di piccola taglia vanno portati in un trasportino rigido e ben chiuso, meglio se abituati in anticipo. I cani vanno condotti al guinzaglio.', $qrir0gr${}$qrir0gr$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('veterinario', 1, 'production', 'info_emergenze', 'Cosa faccio se l''animale sta male fuori orario?', $q1pwkuo$["cosa faccio se sta male di notte","cosa faccio se la clinica e chiusa","dove vado se sta male e siete chiusi","cosa fare in caso di emergenza","cosa faccio se e una emergenza","cosa fare se e un emergenza fuori orario"]$q1pwkuo$::jsonb, 'In caso di emergenza è importante contattare subito la clinica o rivolgersi al pronto soccorso veterinario più vicino, senza aspettare. Non provochi il vomito e non dia farmaci o rimedi all''animale senza indicazione del veterinario.', $q8j2p90${}$q8j2p90$::jsonb);
